function icon(name, size = 22) {
  size = Math.round(size * 1.7);
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name] || ICONS.shield}</svg>`;
}

const DEPARTMENTS = [
 ['cardiology','Cardiology and Cardiac Surgery','heart','treat-heart','Care for the heart, from diagnosis to complex open-heart surgery.','Chennai\u2019s cardiac centres treat thousands of heart patients every year, from routine valve problems to complex re-operations. Your case is assessed by a cardiologist and a cardiac surgeon together, so you receive the treatment that suits your heart, not just the one that is easiest to offer. Modern cardiac ICUs and dedicated cardiac rehabilitation teams support your recovery from the first day after surgery.',['Coronary artery disease and blocked arteries','Heart valve disease','Heart failure','Congenital heart defects in adults','Aortic aneurysm'],['Coronary artery bypass grafting (CABG)','Heart valve repair and replacement','Minimally invasive and keyhole heart surgery','Aortic surgery','Heart transplant evaluation']],
 ['interventional-cardiology','Interventional Cardiology','heart','treat-heart','Heart treatment through small catheters instead of open surgery.','Interventional cardiologists treat many heart conditions through a thin tube passed through a blood vessel in the wrist or groin, with no large incision. Most patients walk within a day and leave hospital within a few days. Advanced catheter labs allow precise imaging of the arteries so that each stent or device is placed exactly where it is needed.',['Blocked or narrowed coronary arteries','Irregular heartbeat (arrhythmia)','Structural heart problems','Heart attack follow-up care'],['Coronary angiography','Angioplasty and stenting','Pacemaker and ICD implantation','TAVI (valve replacement through a catheter)','Electrophysiology study and ablation']],
 ['gastroenterology','Gastroenterology and Hepatology','stomach','treat-digestive','Diagnosis and treatment of the digestive system and liver.','Gastroenterologists and liver specialists diagnose and treat conditions of the oesophagus, stomach, intestines, liver and pancreas. Advanced endoscopy lets doctors see inside the digestive tract, take samples and often treat problems in the same procedure, without surgery. For liver disease, specialists work closely with transplant teams when a transplant may be needed.',['Liver disease and cirrhosis','Inflammatory bowel disease','Acid reflux and ulcers','Pancreatic disorders','Gastrointestinal bleeding'],['Endoscopy and colonoscopy','ERCP for bile duct problems','Endoscopic ultrasound','Liver disease management','Therapeutic endoscopy']],
 ['gi-surgery','GI and Hepatobiliary Surgery','scalpel','treat-digestive','Surgery of the stomach, intestines, liver, pancreas and gall bladder.','Gastrointestinal surgeons operate on the digestive organs, increasingly through keyhole and robotic techniques that mean smaller scars and a faster return home. Complex operations on the liver and pancreas are performed by specialist teams with dedicated intensive care support. Your surgeon reviews your scans before you travel so that your plan is clear from the start.',['Gall stones','Hernia','Colorectal disease','Liver and pancreatic tumours','Stomach and oesophageal conditions'],['Laparoscopic gall bladder removal','Hernia repair','Colorectal surgery','Liver resection','Whipple procedure']],
 ['nephrology','Nephrology','kidney','treat-kidney','Specialist care for kidney disease and kidney failure.','Nephrologists manage every stage of kidney disease, from early diagnosis to dialysis and preparation for a kidney transplant. If you need dialysis during your stay, it is arranged in comfortable, modern units. When a transplant is planned, the nephrology and transplant teams assess both the patient and the donor carefully and in line with Indian law.',['Chronic kidney disease','Kidney failure','Glomerular disease','High blood pressure affecting the kidneys'],['Haemodialysis','Peritoneal dialysis','Kidney biopsy','Kidney transplant evaluation','Long-term kidney care plans']],
 ['urology','Urology','kidney','treat-kidney','Treatment of the urinary tract and male reproductive health.','Urologists treat conditions of the kidneys, bladder, prostate and urinary tract, often with laser and keyhole techniques. Many stone and prostate procedures need only a short hospital stay. Robotic surgery is available for selected urological cancers, offering high precision and faster recovery.',['Kidney and bladder stones','Enlarged prostate','Urological cancers','Urinary incontinence'],['Laser stone removal','Prostate surgery (TURP, HoLEP)','Robotic prostatectomy','Robotic kidney surgery']],
 ['neurology','Neurology','brain','treat-brain','Diagnosis and care of brain, spine and nerve conditions.','Neurologists diagnose and treat conditions that affect the brain, spinal cord and nerves. Advanced imaging, nerve studies and specialist clinics help reach a clear diagnosis, which is the foundation of good treatment. Care plans often combine medicine, rehabilitation and long-term follow-up that can continue by video once you return home.',['Stroke','Epilepsy','Parkinson\u2019s disease and movement disorders','Multiple sclerosis','Headache and migraine'],['Stroke care and rehabilitation','Epilepsy evaluation and monitoring','Movement disorder treatment','Nerve and muscle studies']],
 ['neurosurgery','Neurosurgery','brain','treat-brain','Surgery of the brain, skull base and nervous system.','Neurosurgeons perform delicate operations on the brain and nervous system using navigation systems, operating microscopes and monitoring of nerve function during surgery. These tools help surgeons remove what needs to be removed while protecting healthy tissue. Specialist neuro-intensive care and rehabilitation teams support you after surgery.',['Brain tumours','Aneurysms and vascular malformations','Hydrocephalus','Skull base tumours'],['Brain tumour surgery','Aneurysm treatment','Deep brain stimulation','Epilepsy surgery','Endoscopic skull base surgery']],
 ['spine-surgery','Spine Surgery','spine','treat-bones','Surgical care for the spine, from disc problems to deformity.','Spine surgeons treat back and neck problems when physiotherapy and medicine are no longer enough. Minimally invasive techniques mean smaller incisions, less pain and earlier walking. Complex deformity correction, such as scoliosis surgery, is planned in detail using imaging before you travel.',['Slipped disc','Spinal stenosis','Scoliosis and spinal deformity','Spinal fractures'],['Minimally invasive spine surgery','Spinal fusion','Scoliosis correction','Disc replacement','Spinal decompression']],
 ['orthopaedics','Orthopaedics and Joint Replacement','bone','treat-bones','Bones, joints and muscles, including total joint replacement.','Orthopaedic surgeons in Chennai perform a large number of knee and hip replacements every year, including robot-assisted procedures. Most patients start walking with support within a day of joint replacement. A structured physiotherapy plan begins in hospital and continues during your recovery stay, so you return home moving confidently.',['Arthritis of the knee, hip and shoulder','Fractures and trauma','Joint deformity','Bone infections'],['Knee replacement','Hip replacement','Shoulder replacement','Robotic joint replacement','Revision joint surgery']],
 ['sports-medicine','Sports Medicine and Arthroscopy','run','treat-bones','Treatment for ligament, tendon and sports injuries.','Sports medicine specialists repair ligaments, cartilage and tendons, mostly through keyhole arthroscopy. This approach means small incisions and a faster return to normal activity. Rehabilitation is planned step by step so that the repaired joint regains strength and stability.',['ACL and ligament tears','Meniscus injuries','Shoulder instability','Rotator cuff tears'],['ACL reconstruction','Arthroscopic meniscus repair','Rotator cuff repair','Shoulder stabilisation']],
 ['medical-oncology','Medical Oncology','ribbon','treat-cancer','Cancer treatment with medicines, planned around each patient.','Medical oncologists plan cancer treatment with medicines, including chemotherapy, immunotherapy and targeted therapy. Every plan is discussed by a tumour board, a meeting of surgeons, oncologists and radiologists, so that you benefit from several expert opinions. Day-care units allow many treatments without a hospital stay.',['Breast, lung, colon and other solid cancers','Blood cancers','Head and neck cancers','Gynaecological cancers'],['Chemotherapy','Immunotherapy','Targeted therapy','Hormone therapy','Tumour board review']],
 ['surgical-oncology','Surgical Oncology','scalpel','treat-cancer','Surgery to remove cancer, including robotic cancer surgery.','Surgical oncologists remove tumours while protecting the function of nearby organs as much as possible. Robotic and keyhole techniques are used where suitable to reduce pain and shorten recovery. Surgery is planned alongside medical and radiation oncology so that your whole cancer treatment fits together.',['Solid tumours','Head and neck cancers','Gynaecological cancers','Gastrointestinal cancers'],['Cancer surgery','Robotic cancer surgery','Breast-conserving surgery','Reconstructive surgery after cancer']],
 ['radiation-oncology','Radiation Oncology','radiation','treat-cancer','Precise radiation treatment that targets cancer and protects healthy tissue.','Radiation oncologists use advanced machines that shape the radiation beam to the exact form of the tumour. This protects nearby healthy organs and reduces side effects. Most radiation treatment is given as daily outpatient sessions, so you can stay comfortably at your hotel during the course.',['Most solid cancers','Brain tumours','Cancer that has spread to bones'],['IMRT and IGRT','Stereotactic radiosurgery','Brachytherapy','Palliative radiotherapy']],
 ['haematology','Haematology and Bone Marrow Transplant','drop','treat-bmt','Blood disorders and blood cancers, including bone marrow transplant.','Haematologists treat blood disorders and blood cancers, and specialist units perform bone marrow and stem cell transplants. Transplant units use protected rooms with filtered air to reduce the risk of infection. A bone marrow transplant usually needs a longer stay, and we plan your accommodation and family support for the full period.',['Leukaemia','Lymphoma','Thalassaemia','Aplastic anaemia','Multiple myeloma'],['Bone marrow transplant','Stem cell transplant','Chemotherapy for blood cancers','Thalassaemia management']],
 ['pulmonology','Pulmonology','lungs','treat-brain','Care for the lungs and breathing.','Pulmonologists diagnose and treat lung and breathing problems, from asthma to complex lung disease. Lung function tests, scans and bronchoscopy help reach a precise diagnosis. Treatment plans often include pulmonary rehabilitation to strengthen your breathing.',['Asthma and COPD','Interstitial lung disease','Sleep apnoea','Lung infections'],['Bronchoscopy','Lung function testing','Pulmonary rehabilitation','Sleep studies']],
 ['thoracic-surgery','Thoracic Surgery','lungs','treat-transplant','Surgery of the lungs, chest wall and oesophagus.','Thoracic surgeons operate on the lungs, chest and oesophagus, often through small keyhole incisions known as VATS. Keyhole chest surgery reduces pain and helps patients breathe and move sooner after surgery. Complex cases are discussed with lung and cancer specialists before surgery.',['Lung tumours','Oesophageal disease','Chest wall problems'],['VATS (keyhole chest surgery)','Lung resection','Oesophageal surgery','Lung transplant evaluation']],
 ['endocrinology','Endocrinology and Diabetes','syringe','treat-checkup','Hormone and metabolic conditions, including diabetes and thyroid.','Endocrinologists treat conditions caused by hormones, including diabetes, thyroid problems and pituitary disorders. Good diabetes control also matters before any surgery, so endocrinologists often work alongside your surgical team. You leave with a clear, written long-term plan to continue at home.',['Type 1 and type 2 diabetes','Thyroid disorders','Pituitary and adrenal disorders','Obesity and metabolic conditions'],['Diabetes management programmes','Thyroid treatment','Hormone therapy','Insulin pump planning']],
 ['bariatric-surgery','Bariatric and Metabolic Surgery','scale','treat-digestive','Surgery for severe obesity and related health conditions.','Bariatric surgery helps people with severe obesity achieve lasting weight loss and often improves diabetes and blood pressure. Surgery is done through keyhole techniques, and most patients walk on the same day. Dietitians and doctors guide you before and after surgery, and support continues by video after you return home.',['Severe obesity','Obesity-related diabetes','Obesity-related sleep apnoea'],['Sleeve gastrectomy','Gastric bypass','Revision bariatric surgery']],
 ['general-surgery','General and Laparoscopic Surgery','scalpel','treat-transplant','Common surgical procedures, mostly through keyhole surgery.','General surgeons perform many common operations, most of them through keyhole surgery with small incisions. Keyhole surgery usually means less pain, a shorter hospital stay and a quicker return to daily life. Your surgeon reviews your reports in advance so the plan is clear before you arrive.',['Hernia','Gall stones','Appendicitis','Thyroid nodules'],['Laparoscopic surgery','Hernia repair','Thyroidectomy','Day-care procedures']],
 ['robotic-surgery','Robotic Surgery','robot','treat-transplant','Robot-assisted surgery for greater precision and faster recovery.','In robotic surgery, the surgeon controls fine robotic instruments from a console with a magnified 3D view. This allows very precise movements in small spaces, often with less blood loss and faster recovery. Robotic surgery is used for selected cancers and urological, gynaecological and general surgical procedures.',['Selected cancers','Urological conditions','Gynaecological conditions'],['Robotic prostatectomy','Robotic hysterectomy','Robotic kidney surgery','Robotic colorectal surgery']],
 ['obstetrics-gynaecology','Obstetrics and Gynaecology','female','treat-fertility','Women\u2019s health, pregnancy care and gynaecological surgery.','Gynaecologists treat conditions of the womb, ovaries and pelvis, often using keyhole and robotic surgery. Female doctors are available on request, and your privacy and comfort are respected at every step. High-risk pregnancy specialists work alongside neonatal teams when needed.',['Fibroids','Endometriosis','Ovarian cysts','High-risk pregnancy'],['Hysterectomy','Fibroid removal','Laparoscopic gynaecological surgery','High-risk pregnancy care']],
 ['ivf-fertility','IVF and Fertility','microscope','treat-fertility','Fertility assessment and assisted reproduction.','Fertility specialists assess both partners and recommend the most suitable treatment, from simple steps to IVF. Modern embryology laboratories maintain strict quality standards. IVF cycles need careful timing, and we plan your stay around your treatment calendar.',['Infertility in women and men','Recurrent pregnancy loss','Low ovarian reserve'],['IVF','ICSI','Fertility preservation','Fertility assessment for couples']],
 ['paediatrics','Paediatrics and Neonatology','baby','treat-implants','Specialist care for newborns, infants and children.','Paediatric specialists care for children with a calm, child-friendly approach. Parents can stay with their child, and we arrange family rooms and support throughout. Neonatal intensive care units look after newborns who need specialist care.',['Premature birth care','Childhood illnesses','Growth and development concerns'],['Neonatal intensive care','Paediatric specialist care','Child health assessments']],
 ['paediatric-surgery','Paediatric Surgery and Cardiac Care','baby','treat-heart','Surgery for children, including heart surgery for congenital defects.','Paediatric surgeons and paediatric heart surgeons operate on babies and children, with anaesthesia and intensive care teams trained specifically for children. Many congenital heart defects can be repaired with excellent long-term results. Parents stay close throughout, and our team supports the whole family.',['Congenital heart disease','Birth defects','Childhood hernias and tumours'],['Paediatric heart surgery','Paediatric general surgery','Paediatric urology']],
 ['ent','ENT (Ear, Nose and Throat)','ear','treat-implants','Care for hearing, sinuses, voice and throat.','ENT specialists treat conditions of the ear, nose, throat, head and neck. Cochlear implants can restore hearing for children and adults with severe hearing loss, followed by a programme of hearing therapy. Endoscopic sinus surgery is done without external cuts.',['Hearing loss','Chronic sinusitis','Head and neck tumours','Voice and swallowing problems'],['Cochlear implants','Endoscopic sinus surgery','Ear surgery','Head and neck surgery']],
 ['ophthalmology','Ophthalmology','eye','treat-eyes','Complete eye care, from cataract to retina surgery.','Eye specialists in Chennai are known for advanced cataract, retina and cornea care. Many eye procedures are day-care, so you return to your hotel the same day. Follow-up visits are scheduled before you fly home to make sure your eye has healed well.',['Cataract','Glaucoma','Retinal disease','Corneal disease','Squint'],['Cataract surgery','LASIK and vision correction','Retina surgery','Cornea transplant','Glaucoma surgery']],
 ['dermatology','Dermatology','skin','treat-cosmetic','Treatment of skin, hair and nail conditions.','Dermatologists diagnose and treat long-term skin conditions as well as hair and nail problems. Treatment can include medicines, light therapy and minor procedures. You leave with a clear plan that you can continue at home.',['Psoriasis','Vitiligo','Eczema','Hair loss'],['Phototherapy','Dermatological procedures','Hair loss treatment']],
 ['plastic-surgery','Plastic and Cosmetic Surgery','sparkles','treat-cosmetic','Reconstructive and cosmetic surgery.','Plastic surgeons perform both reconstructive surgery, such as after injury or cancer, and cosmetic procedures. Every procedure starts with an honest consultation about what can realistically be achieved. Your recovery stay is planned so that stitches and follow-up checks are completed before you fly.',['Reconstruction after injury or cancer','Cosmetic concerns','Hair loss'],['Rhinoplasty','Liposuction','Tummy tuck','Hair transplant','Facelift']],
 ['dental','Dental Care','tooth','treat-checkup','Dental treatment from implants to full smile makeovers.','Dental specialists provide treatment from routine care to implants and full-mouth rehabilitation. Treatment is often planned in stages, and we arrange your visits so that as much as possible is completed during your stay. Modern digital imaging helps plan implants precisely.',['Missing teeth','Gum disease','Worn or damaged teeth'],['Dental implants','Full-mouth rehabilitation','Root canal treatment','Crowns and bridges']],
 ['vascular-surgery','Vascular Surgery','vessel','treat-heart','Treatment of arteries and veins.','Vascular surgeons treat problems with arteries and veins, often through small punctures rather than open surgery. Treating blocked leg arteries early can prevent serious complications. Varicose vein treatments are usually day-care procedures.',['Peripheral artery disease','Varicose veins','Aortic aneurysm','Diabetic foot problems'],['Endovascular aneurysm repair','Varicose vein treatment','Peripheral angioplasty','Bypass surgery']],
 ['rheumatology','Rheumatology','bone','treat-bones','Care for arthritis and autoimmune conditions.','Rheumatologists treat inflammatory arthritis and autoimmune conditions that affect joints and other organs. Early, correct diagnosis and the right medicines can protect your joints for the long term. Your plan is shared in writing so your doctor at home can continue it.',['Rheumatoid arthritis','Lupus','Ankylosing spondylitis','Gout'],['Biological therapy','Joint injections','Long-term disease management']],
 ['psychiatry','Psychiatry and Mental Health','mind','journey-interpreter','Confidential mental health assessment and care.','Psychiatrists and psychologists provide confidential assessment and treatment for mental health conditions. Sessions can be held in your language with a trained interpreter. Follow-up care can continue online after you return home.',['Depression','Anxiety','Bipolar disorder','Sleep problems'],['Assessment and treatment plans','Psychological therapy','Medication review']],
 ['rehabilitation','Rehabilitation and Physiotherapy','rehab','treat-bones','Recovery after surgery, stroke or injury.','Rehabilitation helps you regain strength, movement and independence after surgery, stroke or injury. Physiotherapists set clear goals for each day of your recovery. Exercise plans are written for you to continue at home.',['Recovery after surgery','Stroke recovery','Sports injury recovery'],['Physiotherapy','Neuro-rehabilitation','Cardiac rehabilitation','Occupational therapy']],
 ['health-checkups','Executive Health Check-ups','clipboard','treat-checkup','Complete health screening in a single visit.','Executive health check-ups give you a complete picture of your health in one or two days. Tests are tailored to your age, sex and family history. A doctor explains every result to you in person, and any finding that needs attention is followed up straight away.',['Preventive screening','Family history of heart disease or cancer'],['Full body check-up','Cardiac screening','Cancer screening','Women\u2019s health screening']]
].map(([slug,name,ic,img,blurb,about,conditions,procedures]) => ({slug,name,icon:ic,img,blurb,about,conditions,procedures}));

const TREATMENT_GROUPS = [
 {slug:'organ-transplants',name:'Organ transplants',icon:'transplant',img:'treat-transplant',intro:'Kidney, liver, heart, lung and pancreas transplants at accredited transplant centres in Chennai.',about:'Chennai is one of India\u2019s leading centres for organ transplantation, with experienced teams for kidney, liver, heart and lung transplants. Every transplant follows the Transplantation of Human Organs and Tissues Act: donors must be related or legally approved, and a hospital authorisation committee reviews each case. Both patient and donor are assessed carefully before travel, and the whole family is supported through a longer recovery stay.',legal:true,items:[['Kidney transplant','Living related donor transplants with careful matching and long-term follow-up.'],['Liver transplant','Living donor and deceased donor liver transplants by specialist hepatobiliary teams.'],['Heart transplant','For advanced heart failure, with assessment by heart failure specialists.'],['Lung transplant','For end-stage lung disease, after detailed evaluation.'],['Pancreas transplant','Usually combined with kidney transplant for selected diabetic patients.'],['Cornea transplant','Restores clear vision when the cornea is damaged or cloudy.']]},
 {slug:'bone-marrow-transplant',name:'Bone marrow and blood',icon:'drop',img:'treat-bmt',intro:'Bone marrow and stem cell transplants for blood cancers and inherited blood disorders.',about:'Bone marrow and stem cell transplants can cure or control many blood cancers and inherited blood disorders such as thalassaemia. Specialist transplant units use protected rooms with filtered air to reduce infection risk. Treatment usually requires a longer stay, so we plan accommodation, attendant visas and family support for the full period.',items:[['Bone marrow transplant','Replaces diseased bone marrow with healthy cells from a donor or from the patient.'],['Stem cell transplant','Uses blood-forming stem cells collected from blood or marrow.'],['Thalassaemia treatment','Transfusion programmes and transplant evaluation for a possible cure.'],['Leukaemia and lymphoma care','Chemotherapy, targeted therapy and transplant planning.']]},
 {slug:'heart',name:'Heart',icon:'heart',img:'treat-heart',intro:'From angioplasty to bypass and valve surgery, for adults and children.',about:'Cardiac teams in Chennai treat the full range of heart conditions, from blocked arteries to complex valve and congenital problems. Many conditions are now treated through catheters with no large incision. When surgery is needed, dedicated cardiac ICUs and rehabilitation programmes help you recover safely before travelling home.',items:[['Bypass surgery (CABG)','Creates new routes for blood to reach the heart around blocked arteries.'],['Valve repair and replacement','Repairs or replaces damaged heart valves, sometimes through keyhole surgery.'],['Angioplasty and stents','Opens blocked arteries through a thin tube, without open surgery.'],['Paediatric heart surgery','Repairs congenital heart defects in babies and children.'],['Pacemaker implantation','Keeps a slow or irregular heartbeat steady.']]},
 {slug:'cancer-care',name:'Cancer care',icon:'ribbon',img:'treat-cancer',intro:'Complete cancer care planned by a team of specialists.',about:'Every cancer case is discussed by a tumour board, where surgeons, medical oncologists and radiation oncologists agree on the best plan together. Treatment may combine surgery, chemotherapy, radiation, immunotherapy and targeted therapy. Many treatments are given as day care, so you can stay comfortably in your hotel between sessions.',items:[['Chemotherapy','Medicines that destroy or slow the growth of cancer cells.'],['Radiation therapy','Precisely targeted radiation that protects nearby healthy tissue.'],['Immunotherapy','Helps your own immune system recognise and fight cancer.'],['Cancer surgery','Removes tumours while protecting the function of nearby organs.'],['Robotic cancer surgery','High-precision surgery through small incisions for selected cancers.'],['Targeted therapy','Medicines that act on specific features of the cancer cells.']]},
 {slug:'bones-and-joints',name:'Bones and joints',icon:'bone',img:'treat-bones',intro:'Joint replacement, spine and sports injury surgery.',about:'Joint replacement is one of the most common reasons international patients come to Chennai. Most patients walk with support within a day of knee or hip replacement and leave hospital within a few days. A physiotherapy programme starts in hospital and continues during your recovery stay so you return home moving confidently.',items:[['Knee replacement','Replaces a worn knee joint to relieve pain and restore movement.'],['Hip replacement','Replaces a damaged hip joint, often allowing walking the next day.'],['Spine fusion','Stabilises the spine to relieve pain from instability or deformity.'],['Scoliosis correction','Straightens and stabilises a curved spine.'],['ACL repair','Reconstructs a torn knee ligament through keyhole surgery.'],['Shoulder replacement','Restores movement in a severely arthritic shoulder.']]},
 {slug:'brain-and-nerves',name:'Brain and nerves',icon:'brain',img:'treat-brain',intro:'Advanced neurosurgery and neurology care.',about:'Neurosurgeons and neurologists use advanced imaging and navigation to treat complex brain, spine and nerve conditions safely. Monitoring during surgery protects important brain functions. Specialist rehabilitation helps you regain strength and independence after treatment.',items:[['Brain tumour surgery','Removes tumours using navigation systems and operating microscopes.'],['Epilepsy surgery','For seizures that do not respond well to medicines.'],['Deep brain stimulation','Reduces tremors in Parkinson\u2019s disease and some movement disorders.'],['Stroke care','Rapid treatment and structured rehabilitation after stroke.']]},
 {slug:'digestive-and-weight',name:'Digestive and weight loss',icon:'stomach',img:'treat-digestive',intro:'Keyhole and robotic surgery for the digestive system, and bariatric surgery.',about:'Digestive surgeons and gastroenterologists treat conditions of the stomach, intestines, liver, pancreas and gall bladder, mostly with keyhole techniques. Bariatric surgery helps people with severe obesity lose weight and often improves diabetes. You receive dietary guidance before and after surgery, with follow-up by video once home.',items:[['Bariatric surgery','Sleeve gastrectomy or gastric bypass for lasting weight loss.'],['Gall bladder surgery','Keyhole removal of the gall bladder, usually with a short stay.'],['Hernia repair','Keyhole or open repair with mesh for a strong, lasting result.'],['Liver resection','Removes part of the liver affected by tumours or disease.'],['Colorectal surgery','Treats conditions and cancers of the bowel and rectum.']]},
 {slug:'kidney-and-urinary',name:'Kidney and urinary',icon:'kidney',img:'treat-kidney',intro:'Dialysis, stone removal and prostate care.',about:'Kidney and urology specialists treat conditions from kidney stones to kidney failure. Laser and keyhole techniques mean most stone and prostate procedures need only a short stay. Comfortable dialysis units are available for patients who need dialysis during their visit.',items:[['Dialysis','Haemodialysis sessions in modern, comfortable units during your stay.'],['Kidney stone removal','Laser and keyhole removal of stones, usually without open surgery.'],['Prostate surgery','Relieves urinary symptoms from an enlarged prostate.']]},
 {slug:'implants',name:'Implants',icon:'ear',img:'treat-implants',intro:'Hearing, dental, cardiac and joint implants.',about:'Medical implants restore function that the body has lost, from hearing to heart rhythm and joint movement. Each implant is chosen carefully for your needs and fitted by an experienced specialist. Follow-up and device checks are planned before you return home.',items:[['Cochlear implants','Restore hearing for children and adults with severe hearing loss.'],['Dental implants','Replace missing teeth with secure, natural-looking implants.'],['Pacemakers','Keep the heartbeat steady when it is too slow or irregular.'],['Joint implants','Replace worn joints in the knee, hip or shoulder.']]},
 {slug:'women-and-fertility',name:'Women\u2019s health and fertility',icon:'microscope',img:'treat-fertility',intro:'Fertility treatment and gynaecological surgery.',about:'Fertility specialists and gynaecologists provide care with privacy, respect and female doctors available on request. Modern embryology laboratories support IVF and related treatments. Gynaecological surgery is often done through keyhole or robotic techniques for a faster recovery.',items:[['IVF','Fertilisation in the laboratory with careful embryo selection.'],['Hysterectomy','Removal of the womb, often through keyhole or robotic surgery.'],['Fibroid removal','Removes fibroids while preserving the womb where possible.'],['High-risk pregnancy care','Specialist monitoring for mothers and babies who need extra care.']]},
 {slug:'eyes',name:'Eyes',icon:'eye',img:'treat-eyes',intro:'Vision-restoring surgery with advanced technology.',about:'Chennai\u2019s eye hospitals are known for advanced cataract, retina and cornea care. Most eye procedures are day care, so you return to your hotel the same day. Follow-up checks are completed before you fly home.',items:[['Cataract surgery','Replaces a cloudy lens with a clear artificial lens.'],['LASIK','Laser vision correction to reduce dependence on glasses.'],['Retina surgery','Treats retinal detachment, diabetic eye disease and other retinal problems.'],['Glaucoma treatment','Protects the optic nerve by controlling eye pressure.'],['Cornea transplant','Replaces a damaged cornea to restore clear vision.']]},
 {slug:'cosmetic',name:'Cosmetic and reconstructive',icon:'sparkles',img:'treat-cosmetic',intro:'Cosmetic and reconstructive procedures by experienced plastic surgeons.',about:'Plastic surgeons offer both reconstructive procedures after injury or cancer and cosmetic procedures. Every plan begins with an honest consultation about realistic results. Your recovery stay allows stitches and checks to be completed before you travel.',items:[['Rhinoplasty','Reshapes the nose for appearance or breathing.'],['Liposuction','Removes stubborn fat from targeted areas.'],['Tummy tuck','Tightens the abdomen and removes excess skin.'],['Hair transplant','Moves healthy hair follicles to thinning areas.'],['Facelift','Lifts and firms the face and neck.']]},
 {slug:'check-ups',name:'Health check-ups',icon:'clipboard',img:'treat-checkup',intro:'Preventive screening completed in one or two days.',about:'A health check-up gives you a complete picture of your health in one or two days. Tests are tailored to your age, sex and family history. A doctor explains each result in person, and any finding is followed up straight away.',items:[['Full body check-up','Blood tests, scans and consultations covering major body systems.'],['Cardiac screening','ECG, echo and stress tests for heart health.'],['Cancer screening','Screening tests chosen for your age, sex and family history.']]}
];

